 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full zero rows/columns are the dividers between independent panels.
    sep_rows = {r for r in range(h) if all(v == 0 for v in grid[r])}
    sep_cols = {c for c in range(w) if all(grid[r][c] == 0 for r in range(h))}

    def spans(n, separators):
        out = []
        start = 0
        for i in range(n):
            if i in separators:
                if start < i:
                    out.append((start, i))
                start = i + 1
        if start < n:
            out.append((start, n))
        return out

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)
    result = []
    for r0, r1 in row_spans:
        row = []
        for c0, c1 in col_spans:
            colors = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
            row.append(1 if len(colors) > 1 else 0)
        result.append(row)
    return result

