 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    row_seps = [r for r in range(h) if len(set(grid[r])) == 1]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(size, separators):
        parts = []
        start = 0
        for i in separators:
            if start < i:
                parts.append((start, i))
            start = i + 1
        if start < size:
            parts.append((start, size))
        return parts

    result = []
    for r0, r1 in spans(h, row_seps):
        row = []
        for c0, c1 in spans(w, col_seps):
            counts = {}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    counts[v] = counts.get(v, 0) + 1
            background = max(counts, key=counts.get)
            foreground_count = sum(n for color, n in counts.items() if color != background)
            # A two-mark panel is encoded as 1; a singleton retains its background color.
            row.append(1 if foreground_count == 2 else background)
        result.append(row)
    return result
